    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != background]
    for i, (r1, c1, color) in enumerate(points):
        for r2, c2, color2 in points[i + 1:]:
            if color != color2:
                continue
            if r1 == r2:
                for c in range(min(c1, c2) + 1, max(c1, c2)):
                    if out[r1][c] == background:
                        out[r1][c] = 3
            elif c1 == c2:
                for r in range(min(r1, r2) + 1, max(r1, r2)):
